export interface CloudMetadata {
  provider: 'AWS' | 'Azure' | 'GCP' | 'Kubernetes' | 'OnPrem' | string;
  resourceId: string; // e.g., ARN, Azure Resource ID
  region?: string;
  accountId?: string; // AWS Account ID, Azure Subscription ID, GCP Project ID
  resourceType?: string; // e.g., 'AWS::RDS::DBInstance'
  resourceName?: string;
  providerMetadata?: Record<string, any>; // Extensible provider-specific fields (e.g., storageClass)
}

import { LifecycleStatus } from './Lifecycle';
import { Ownership } from './Ownership';
import { CloudMetadata } from './CloudMetadata';
import { Tags } from './Tags';

export interface ConfigurationItem {
  ciId: string;
  externalId?: string;
  name: string;
  displayName?: string;
  type: string; // e.g., 'Application', 'Database', 'BusinessService'
  subType?: string;
  environment?: string;
  businessCriticality?: 'MissionCritical' | 'BusinessCritical' | 'Important' | 'Standard' | 'Low';
  lifecycleStatus: LifecycleStatus;
  
  ownership?: Ownership;
  
  tags?: Tags;
  labels?: string[];
  
  version?: string;
  
  createdAt: Date;
  updatedAt: Date;
  
  cloudMetadata?: CloudMetadata;
  customAttributes?: Record<string, any>; // For extensible attributes
}

import { CMDBRepository } from '../registry/CMDBRepository';
import { ConfigurationItem } from '../domain/ConfigurationItem';

export class ImpactAnalyzer {
  constructor(private readonly repository: CMDBRepository) {}

  /**
   * Identifies all upstream CIs that would be impacted if the given CI fails.
   */
  async analyzeImpact(failedCiId: string): Promise<ConfigurationItem[]> {
    const impacted = new Map<string, ConfigurationItem>();
    
    // Breadth-first traversal up the dependency chain
    const queue = [failedCiId];
    
    while (queue.length > 0) {
      const currentId = queue.shift()!;
      const dependents = await this.repository.getUpstreamDependencies(currentId);
      
      for (const rel of dependents) {
        if (!impacted.has(rel.sourceCiId)) {
          const ci = await this.repository.getConfigurationItem(rel.sourceCiId);
          if (ci) {
            impacted.set(ci.ciId, ci);
            queue.push(ci.ciId);
          }
        }
      }
    }
    
    return Array.from(impacted.values());
  }
}
